import com.saloeater.translations_extractor.module.EffectsModule;
import com.saloeater.translations_extractor.module.EnchantmentsModule;
import com.saloeater.translations_extractor.module.LangModule;
import com.saloeater.translations_extractor.module.Module;
import com.saloeater.translations_extractor.module.ModuleResult;
import com.saloeater.translations_extractor.module.PatchouliModule;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

public class ModuleManager {
    private final Map<String, Module> modules = new HashMap<String, Module>();

    public ModuleManager() {
        this.registerModules();
    }

    private void registerModules() {
        this.registerModule(new LangModule());
        this.registerModule(new PatchouliModule());
        this.registerModule(new EnchantmentsModule());
        this.registerModule(new EffectsModule());
    }

    private void registerModule(Module module) {
        this.modules.put(module.getName(), module);
    }

    public Set<String> getModuleNames() {
        return this.modules.keySet();
    }

    public ModuleResult execute(String moduleName, Path resourcePackPath, boolean onlyMissing) {
        Module module = this.modules.get(moduleName);
        if (module == null) {
            return ModuleResult.empty();
        }
        return module.execute(resourcePackPath, onlyMissing);
    }
}

