extends CraftingTableBlock {
    private static final Component TITLE = TextUtil.translatable((String)"container.uncraftingtable76.uncrafting");
    public static UncraftingTableBlock UNCRAFTING_TABLE = new UncraftingTableBlock(CompatibleBlockSettings.of((CompatibleMaterial)CompatibleMaterial.WOOD).strength(2.5f).sounds(SoundType.f_56736_));

    public UncraftingTableBlock(CompatibleBlockSettings settings) {
        super(settings.build());
    }

    public InteractionResult m_6227_(BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        return super.m_6227_(state, world, pos, player, hand, hit);
    }

    public MenuProvider m_7246_(BlockState state, Level world, BlockPos pos) {
        return new SimpleMenuProvider((i, playerInventory, playerEntity) -> new UncraftingScreenHandler(i, playerInventory), TITLE);
    }
}

